<?php
require __DIR__.'/../../../config/database.php';
$entity=(string)($_GET['entidade']??'');$id=(int)($_GET['registro_id']??0);
$stmt=$conn->prepare('SELECT a.*,u.nome AS operador FROM auditoria a LEFT JOIN usuarios u ON u.id=a.usuario_id WHERE (?=\'\' OR a.entidade=?) AND (?=0 OR a.registro_id=?) ORDER BY a.id DESC'.pagination_sql());
$stmt->bind_param('ssii',$entity,$entity,$id,$id);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);pagination($rows);
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Histórico</title><link rel="stylesheet" href="<?= esc(base_url('assets/css/app.css')) ?>"></head><body><main class="admin-main"><a href="<?= esc(base_url()) ?>">Voltar ao painel</a><h1>Histórico operacional</h1><form method="get"><label>Entidade<select name="entidade"><option value="">Todas</option><?php foreach(['moradores','encomendas','visitantes','veiculos','avisos','usuarios'] as $option):?><option <?= $entity===$option?'selected':'' ?>><?= $option ?></option><?php endforeach ?></select></label><label>ID do registro<input name="registro_id" type="number" min="0" value="<?= $id ?>"></label><button>Filtrar</button></form><table><thead><tr><th>Quando</th><th>Operador</th><th>Registro</th><th>Ação</th><th>Detalhes</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?= esc($row['criado_em']) ?></td><td><?= esc($row['operador']??'Sistema') ?></td><td><?= esc($row['entidade'].' #'.$row['registro_id']) ?></td><td><?= esc($row['acao']) ?></td><td><?= esc($row['detalhes']) ?></td></tr><?php endforeach ?></tbody></table><?php pagination_links() ?></main></body></html>
